  private import ScalarValues::*;
  part def Controller {
    in attribute io_0 : Boolean;
    attribute modeBlinking : Boolean := false;
    attribute previousPressed : Boolean := true;
    perform action tick {
      first start;
      then if ((io_0) and ((not previousPressed))) {
        first start;
        then assign modeBlinking := (if modeBlinking ? false else true);
